from AlgorithmImports import *
from math import floor


class SpecifiedStrategySystem(QCAlgorithm):

    SMA_PERIOD = 20
    RSI_PERIOD = 14

    def Initialize(self):
        self.SetStartDate(2006, 1, 3)
        self.SetEndDate(2015, 12, 31)
        self.SetCash(1_000_000)

        self.symbols = {}
        for ticker in ["SPY", "AAPL", "IBM", "BAC", "AIG"]:
            self.symbols[ticker] = self.AddEquity(ticker, Resolution.Daily).Symbol

        self.spy = self.symbols["SPY"]
        self.aapl = self.symbols["AAPL"]

        self.spy_sma = SimpleMovingAverage(self.SMA_PERIOD)
        self.aapl_rsi = RelativeStrengthIndex(self.RSI_PERIOD)
        self.spy_sma_history = RollingWindow[float](2)

        self.aapl_previous_close = None
        self.aapl_red_streak = 0

        self.lots = {"A": 0, "B": 0}
        self.pending_orders = {"A": None, "B": None}
        self.order_slots = {}

    def OnData(self, data: Slice):
        self._update_market_state(data)

        if not all(data.Bars.ContainsKey(symbol) for symbol in self.symbols.values()):
            return

        if not self._ready_to_trade():
            return

        # Sells are evaluated before buys.
        self._evaluate_sell_a()
        self._evaluate_sell_b()
        self._evaluate_buy_a(data.Bars[self.spy].Close)
        self._evaluate_buy_b(data.Bars[self.aapl].Close)

    def _update_market_state(self, data: Slice):
        if data.Bars.ContainsKey(self.spy):
            spy_bar = data.Bars[self.spy]
            self.spy_sma.Update(IndicatorDataPoint(spy_bar.EndTime, spy_bar.Close))
            if self.spy_sma.IsReady:
                self.spy_sma_history.Add(float(self.spy_sma.Current.Value))

        if data.Bars.ContainsKey(self.aapl):
            aapl_bar = data.Bars[self.aapl]

            if self.aapl_previous_close is not None and aapl_bar.Close < self.aapl_previous_close:
                self.aapl_red_streak += 1
            else:
                self.aapl_red_streak = 0

            self.aapl_previous_close = aapl_bar.Close
            self.aapl_rsi.Update(IndicatorDataPoint(aapl_bar.EndTime, aapl_bar.Close))

    def _ready_to_trade(self):
        return (
            self.spy_sma.IsReady
            and self.spy_sma_history.IsReady
            and self.aapl_rsi.IsReady
            and self.aapl_previous_close is not None
        )

    def _evaluate_sell_a(self):
        if self.lots["A"] <= 0 or self.pending_orders["A"] is not None:
            return

        spy_bar = self.CurrentSlice.Bars[self.spy]
        previous_close = self.spy_sma_history[1]
        previous_sma = self.spy_sma_history[1]
        current_sma = self.spy_sma_history[0]

        # Previous SPY close is reconstructed from the SMA-cross state stored
        # through the daily price history below.
        previous_price = self._previous_spy_close
        current_price = spy_bar.Close

        if previous_price >= previous_sma and current_price < current_sma:
            self._submit_order("A", self.spy, -self.lots["A"])

    def _evaluate_sell_b(self):
        if self.lots["B"] <= 0 or self.pending_orders["B"] is not None:
            return

        if self.aapl_rsi.Current.Value > 60:
            self._submit_order("B", self.aapl, -self.lots["B"])

    def _evaluate_buy_a(self, close):
        if self.lots["A"] != 0 or self.pending_orders["A"] is not None:
            return

        if not hasattr(self, "_previous_spy_close"):
            return

        previous_sma = self.spy_sma_history[1]
        current_sma = self.spy_sma_history[0]

        if self._previous_spy_close <= previous_sma and close > current_sma:
            quantity = int(floor((self.Portfolio.TotalPortfolioValue * 0.40) / close))
            if quantity > 0:
                self._submit_order("A", self.spy, quantity)

    def _evaluate_buy_b(self, close):
        if self.lots["B"] != 0 or self.pending_orders["B"] is not None:
            return

        if self.aapl_red_streak >= 3 and self.Portfolio.Cash >= 20_000:
            quantity = int(floor(20_000 / close))
            if quantity > 0:
                self._submit_order("B", self.aapl, quantity)

    def _submit_order(self, slot, symbol, quantity):
        ticket = self.MarketOrder(symbol, quantity)
        self.pending_orders[slot] = ticket.OrderId
        self.order_slots[ticket.OrderId] = slot

    def OnOrderEvent(self, order_event: OrderEvent):
        if order_event.OrderId not in self.order_slots:
            return

        slot = self.order_slots[order_event.OrderId]

        if order_event.FillQuantity != 0:
            self.lots[slot] += order_event.FillQuantity

        if order_event.Status in [OrderStatus.Filled, OrderStatus.Canceled, OrderStatus.Invalid]:
            self.pending_orders[slot] = None
            del self.order_slots[order_event.OrderId]

    def OnEndOfDay(self, symbol):
        if symbol == self.spy and self.CurrentSlice.Bars.ContainsKey(self.spy):
            self._previous_spy_close = self.CurrentSlice.Bars[self.spy].Close

