from AlgorithmImports import *
from collections import deque


class PrivateLotStrategies(QCAlgorithm):

    MA_PERIOD = 50

    def Initialize(self):
        self.SetStartDate(2006, 1, 3)
        self.SetEndDate(2015, 12, 31)
        self.SetCash(1_000_000)

        self.spy = self.AddEquity("SPY", Resolution.Daily).Symbol
        self.aapl = self.AddEquity("AAPL", Resolution.Daily).Symbol
        self.ibm = self.AddEquity("IBM", Resolution.Daily).Symbol
        self.bac = self.AddEquity("BAC", Resolution.Daily).Symbol
        self.aig = self.AddEquity("AIG", Resolution.Daily).Symbol
        self.symbols = [self.spy, self.aapl, self.ibm, self.bac, self.aig]

        self.strategy_a_lot = 0
        self.strategy_b_lot = 0

        self.spy_closes = deque(maxlen=self.MA_PERIOD)
        self.previous_spy_close = None
        self.previous_spy_ma = None

        self.previous_aapl_close = None
        self.aapl_red_streak = 0
        self.rsi_changes = 0
        self.rsi_average_gain = None
        self.rsi_average_loss = None
        self.aapl_rsi = None

    def OnData(self, data: Slice):
        self._update_market_state(data)

        if any(symbol not in data.Bars for symbol in self.symbols):
            return

        if not self._rules_ready():
            return

        spy_close = data.Bars[self.spy].Close
        aapl_close = data.Bars[self.aapl].Close

        spy_crosses_below_ma = (
            self.previous_spy_close <= self.previous_spy_ma
            and spy_close < self._current_spy_ma()
        )

        spy_crosses_above_ma = (
            self.previous_spy_close <= self.previous_spy_ma
            and spy_close > self._current_spy_ma()
        )

        available_cash = self.Portfolio.Cash

        # Sells before buys.
        if self.strategy_a_lot > 0 and spy_crosses_below_ma:
            self.MarketOrder(self.spy, -self.strategy_a_lot)
            available_cash += self.strategy_a_lot * spy_close
            self.strategy_a_lot = 0

        if self.strategy_b_lot > 0 and self.aapl_rsi > 60:
            self.MarketOrder(self.aapl, -self.strategy_b_lot)
            available_cash += self.strategy_b_lot * aapl_close
            self.strategy_b_lot = 0

        if self.strategy_a_lot == 0 and spy_crosses_above_ma:
            quantity = int((0.40 * self.Portfolio.TotalPortfolioValue) // spy_close)
            if quantity > 0:
                self.MarketOrder(self.spy, quantity)
                self.strategy_a_lot = quantity
                available_cash -= quantity * spy_close

        if self.strategy_b_lot == 0 and self.aapl_red_streak >= 3:
            if available_cash >= 20_000:
                quantity = int(20_000 // aapl_close)
                if quantity > 0:
                    self.MarketOrder(self.aapl, quantity)
                    self.strategy_b_lot = quantity

    def _update_market_state(self, data: Slice):
        if self.spy in data.Bars:
            spy_close = data.Bars[self.spy].Close
            self.spy_closes.append(spy_close)

            if len(self.spy_closes) == self.MA_PERIOD:
                current_ma = self._current_spy_ma()
                if self.previous_spy_close is not None:
                    self.previous_spy_ma = (
                        sum(list(self.spy_closes)[:-1]) / (self.MA_PERIOD - 1)
                        if self.previous_spy_ma is None
                        else self.previous_spy_ma
                    )
                self.previous_spy_close = spy_close

        if self.aapl in data.Bars:
            aapl_close = data.Bars[self.aapl].Close

            if self.previous_aapl_close is not None:
                if aapl_close < self.previous_aapl_close:
                    self.aapl_red_streak += 1
                else:
                    self.aapl_red_streak = 0

                change = aapl_close - self.previous_aapl_close
                gain = max(change, 0)
                loss = max(-change, 0)

                self.rsi_changes += 1

                if self.rsi_changes <= 14:
                    if self.rsi_average_gain is None:
                        self.rsi_average_gain = 0
                        self.rsi_average_loss = 0

                    self.rsi_average_gain += gain
                    self.rsi_average_loss += loss

                    if self.rsi_changes == 14:
                        self.rsi_average_gain /= 14
                        self.rsi_average_loss /= 14
                        self.aapl_rsi = self._calculate_rsi()
                else:
                    self.rsi_average_gain = ((self.rsi_average_gain * 13) + gain) / 14
                    self.rsi_average_loss = ((self.rsi_average_loss * 13) + loss) / 14
                    self.aapl_rsi = self._calculate_rsi()

            self.previous_aapl_close = aapl_close

        if self.spy in data.Bars and len(self.spy_closes) == self.MA_PERIOD:
            spy_close = data.Bars[self.spy].Close
            current_ma = self._current_spy_ma()
            if self.previous_spy_ma is not None:
                self.previous_spy_ma = self.previous_spy_ma
            else:
                self.previous_spy_ma = current_ma

    def _current_spy_ma(self):
        return sum(self.spy_closes) / self.MA_PERIOD

    def _calculate_rsi(self):
        if self.rsi_average_loss == 0:
            return 100.0
        rs = self.rsi_average_gain / self.rsi_average_loss
        return 100 - (100 / (1 + rs))

    def _rules_ready(self):
        return (
            len(self.spy_closes) == self.MA_PERIOD
            and self.previous_spy_close is not None
            and self.previous_spy_ma is not None
            and self.aapl_rsi is not None
        )

