            self.aapl_rsi.Update(aapl_bar.EndTime, aapl_bar.Close)

        if not all(symbol in data.Bars for symbol in self.symbols):
            if spy_bar is not None:
                self.spy_previous_close = float(spy_bar.Close)
                if self.spy_sma.IsReady:
                    self.spy_previous_sma = float(self.spy_sma.Current.Value)

            if aapl_bar is not None:
                self.aapl_previous_close = float(aapl_bar.Close)

            return

        spy_close = float(spy_bar.Close)
        aapl_close = float(aapl_bar.Close)
        spy_sma_value = float(self.spy_sma.Current.Value) if self.spy_sma.IsReady else None

        strategy_a_ready = (
            self.spy_sma.IsReady
            and self.spy_previous_close is not None
            and self.spy_previous_sma is not None
        )

        strategy_b_ready = (
            self.aapl_rsi.IsReady
            and self.aapl_previous_close is not None
        )

