        self.bac = self.AddEquity("BAC", Resolution.Daily).Symbol
        self.aig = self.AddEquity("AIG", Resolution.Daily).Symbol
        self.symbols = [self.spy, self.aapl, self.ibm, self.bac, self.aig]

        self.SetWarmUp(101, Resolution.Daily)

        self.spy_closes = deque()
        self.spy_close_sum = 0.0
        self.spy_previous_close = None

        self.aapl_previous_close = None
        self.aapl_red_streak = 0
        self.aapl_rsi = RelativeStrengthIndex(
            14, MovingAverageType.Wilders
        )

        self.strategy_a_lot = 0
        self.strategy_b_lot = 0

    def OnData(self, data: Slice):
        # Keep market-state calculations current whenever a ticker has a bar.
        if data.Bars.ContainsKey(self.spy):
            self._update_spy_state(data.Bars[self.spy])

        if data.Bars.ContainsKey(self.aapl):
            self._update_aapl_state(data.Bars[self.aapl])

        if self.IsWarmingUp:
            return

        # All rule evaluation is skipped unless every subscription has today's bar.
        for symbol in self.symbols:
            if not data.Bars.ContainsKey(symbol):
                return

        spy_bar = data.Bars[self.spy]
        aapl_bar = data.Bars[self.aapl]

        if not self._rules_ready():
            return

        current_spy_sma = self.spy_close_sum / 100.0
        previous_spy_sma = (
            self.spy_close_sum - float(spy_bar.Close) + float(self.spy_previous_close)
        ) / 100.0

        spy_crosses_above = (
            float(self.spy_previous_close) <= previous_spy_sma
            and float(spy_bar.Close) > current_spy_sma
        )
        spy_crosses_below = (
            float(self.spy_previous_close) >= previous_spy_sma
            and float(spy_bar.Close) < current_spy_sma
        )

        # Sells are evaluated before buys.
        if self.strategy_a_lot > 0 and spy_crosses_below:
            self.MarketOrder(self.spy, -self.strategy_a_lot)
            self.strategy_a_lot = 0

        if self.strategy_b_lot > 0 and self.aapl_rsi.Current.Value > 60:
            self.MarketOrder(self.aapl, -self.strategy_b_lot)
            self.strategy_b_lot = 0

        if self.strategy_a_lot == 0 and spy_crosses_above:
            quantity = int(
                (float(self.Portfolio.TotalPortfolioValue) * 0.40)
                / float(spy_bar.Close)
            )
            if quantity > 0:
                self.MarketOrder(self.spy, quantity)
                self.strategy_a_lot = quantity

        if self.strategy_b_lot == 0 and self.aapl_red_streak >= 3:
            if self.Portfolio.Cash >= 20_000:
                quantity = int(20_000 / float(aapl_bar.Close))
                if quantity > 0:
                    self.MarketOrder(self.aapl, quantity)
                    self.strategy_b_lot = quantity

    def _update_spy_state(self, bar: TradeBar):
        close = float(bar.Close)

        if len(self.spy_closes) == 100:
            self.spy_close_sum -= self.spy_closes.popleft()

        self.spy_closes.append(close)
        self.spy_close_sum += close
        self.spy_previous_close = (
            self.spy_closes[-2] if len(self.spy_closes) >= 2 else None
        )

    def _update_aapl_state(self, bar: TradeBar):
        close = float(bar.Close)

        if self.aapl_previous_close is not None:
            if close < self.aapl_previous_close:
                self.aapl_red_streak += 1
            else:
                self.aapl_red_streak = 0

        self.aapl_previous_close = close
        self.aapl_rsi.Update(bar.EndTime, bar.Close)

    def _rules_ready(self) -> bool:
        return (
            len(self.spy_closes) == 100
            and self.spy_previous_close is not None
            and self.aapl_previous_close is not None
            and self.aapl_rsi.IsReady
        )

